import{_ as o,o as a,c as r,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"大模型独立思考记录（llm_reco 推理日志）","description":"","frontmatter":{},"headers":[],"relativePath":"llm_reco/reasoning-log.md","filePath":"llm_reco/reasoning-log.md"}'),n={name:"llm_reco/reasoning-log.md"};function l(e,t,i,d,u,g){return a(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="大模型独立思考记录-llm-reco-推理日志" tabindex="-1">大模型独立思考记录（llm_reco 推理日志） <a class="header-anchor" href="#大模型独立思考记录-llm-reco-推理日志" aria-label="Permalink to &quot;大模型独立思考记录（llm_reco 推理日志）&quot;">​</a></h1><blockquote><p>版本：v0.2（2026-07-29） 目的：记录我（大模型）<strong>不依赖 WIKI 攻略页/官方推荐榜</strong>，仅凭角色原始数据与系统机制页，独立推导&quot;谁是强角色&quot;的全过程。 配套脚本：<code>_signal_extract.py</code>（信号抽取）、<code>_detail.py</code>（候选原文核验）；产物：<code>_signals.txt</code>、<code>_details.txt</code>。</p></blockquote><hr><h2 id="_0-本次推理的边界与原则" tabindex="-1">0. 本次推理的边界与原则 <a class="header-anchor" href="#_0-本次推理的边界与原则" aria-label="Permalink to &quot;0. 本次推理的边界与原则&quot;">​</a></h2><p>我<strong>故意不读取</strong> <code>raid-recommended</code>（官方讨伐战强度榜）和 <code>beginner-guide</code>（官方新手指南点名）里的&quot;推荐名单&quot;。 原因：v0.1 把这些名单当成了结论本身，等于&quot;别人说谁强，我就说谁强&quot;——这是循环论证，且官方榜本身受版本、主观偏好、柯伊伯（Kuipor）当期卡池影响，并不等于机制上的客观强度。</p><p>我<strong>只读取</strong>：</p><ul><li><code>char_data.json</code>：370 名角色的 五维 / 必杀技 / 固有效果（中日双语文本）。</li><li><code>game-mechanics.md</code> 中<strong>系统机制类</strong>的事实（伤害公式、intro、必杀连锁、装备&quot;超昂金&quot;等）——这些是规则，不是推荐。</li></ul><p>我的立场：<strong>强不强，由&quot;机制在伤害/生存公式里的位置 + 该机制的稀有度 + 满突成本&quot;决定</strong>，不由任何榜单决定。</p><hr><h2 id="_1-第一步-把-370-个角色压成可比较的信号" tabindex="-1">1. 第一步：把 370 个角色压成可比较的信号 <a class="header-anchor" href="#_1-第一步-把-370-个角色压成可比较的信号" aria-label="Permalink to &quot;1. 第一步：把 370 个角色压成可比较的信号&quot;">​</a></h2><p>370 人全文读不完，也没必要。我写了 <code>_signal_extract.py</code>，产出三类信号：</p><ol><li><strong>总表</strong>：每个角色的 稀有度 / 阵营 / 攻型 / 五维 / 获取 / 机制标签。</li><li><strong>五维榜 top20</strong>：看属性上限与分布。</li><li><strong>机制分组</strong>：按关键词把&quot;拥有某类固有效果&quot;的角色归到一起，数出每类有多少人。</li></ol><blockquote><p>局限说明（诚实记录）：机制标签是<strong>关键词粗筛</strong>，会有误报/漏报。例如&quot;魔法buff&quot;只命中 1 人，但核验原文后发现她其实是&quot;敌方防速-20% 的减益&quot;，并非给队友加魔法。所以我对关键候选又跑了 <code>_detail.py</code> 打印<strong>完整原文</strong>做二次核验——日志第 4 节的所有结论都基于核验后的原文。</p></blockquote><hr><h2 id="_2-第二步-数据驱动的关键观察" tabindex="-1">2. 第二步：数据驱动的关键观察 <a class="header-anchor" href="#_2-第二步-数据驱动的关键观察" aria-label="Permalink to &quot;2. 第二步：数据驱动的关键观察&quot;">​</a></h2><h3 id="观察-1-满级五维高度收敛-属性不是区分度" tabindex="-1">观察 1：满级五维高度收敛，属性不是区分度 <a class="header-anchor" href="#观察-1-满级五维高度收敛-属性不是区分度" aria-label="Permalink to &quot;观察 1：满级五维高度收敛，属性不是区分度&quot;">​</a></h3><ul><li>攻击上限 521、魔法上限 521、魔抗上限 522、体力上限 3200、防御上限 500。</li><li>绝大多数 SSR 的满级值是 <strong>3050 / 500 / 475 / …</strong>，大量角色完全相同。</li><li><strong>推论</strong>：在同为满级的前提下，A 比 B 多 21 点攻击，对伤害公式影响微乎其微。<strong>真正拉开差距的是固有效果（机制），不是数值。</strong> v0.1 按&quot;攻击力排行榜&quot;挑人，方向就偏了。</li></ul><h3 id="观察-2-不撤退-是极稀有的站场机制" tabindex="-1">观察 2：&quot;不撤退&quot;是极稀有的站场机制 <a class="header-anchor" href="#观察-2-不撤退-是极稀有的站场机制" aria-label="Permalink to &quot;观察 2：&quot;不撤退&quot;是极稀有的站场机制&quot;">​</a></h3><p>全游戏仅 <strong>8 人</strong> 拥有&quot;体力耗尽不撤退，直到受伤才离场&quot;： FM77(R)、神騎フローレル(R)、閃忍マユリ(R)、閃忍レイナ(R)、神騎プロキオン(SR)、ビートソニック・アキレス(SSR)、ブライドハルカ・リバース(SSR)、真夏のハルカ(SSR)。</p><ul><li>其中 <strong>4 个是 R/SR</strong>——意味着新手用极低成本就能拿到&quot;变相延长输出/站场时间&quot;的核心机制。</li><li>在&quot;体力随时间流失&quot;的规则下，这直接对抗游戏的<strong>核心失败条件</strong>（退场=减员）。价值应给极高权重。</li></ul><h3 id="观察-3-速度辅助-充能辅助-极度普遍-不能当稀有卖点" tabindex="-1">观察 3：速度辅助 / 充能辅助&quot;极度普遍&quot;，不能当稀有卖点 <a class="header-anchor" href="#观察-3-速度辅助-充能辅助-极度普遍-不能当稀有卖点" aria-label="Permalink to &quot;观察 3：速度辅助 / 充能辅助&quot;极度普遍&quot;，不能当稀有卖点&quot;">​</a></h3><ul><li>速度辅助：<strong>126 人</strong>。充能辅助：<strong>105 人</strong>。AoE 全体：<strong>247 人</strong>。</li><li><strong>推论</strong>：v0.1 把&quot;闪忍彩香 300% 速度&quot;&quot;神骑参宿四 全队充能&quot;当成稀缺亮点，是受了官方榜的暗示。事实上 259 个 SSR 里一大半都带速度/充能。<strong>R 卡的速度/充能价值，只在&quot;新手还没有 SSR 辅助&quot;时才成立</strong>；满编老玩家眼里这只是通胀技能。</li><li>所以我给这类 R 卡的定位是&quot;新手过渡/低成本补位&quot;，而非&quot;版本答案&quot;。</li></ul><h3 id="观察-4-真正稀缺的是-攻击增益-魔法增益-破防-减伤-复活-全异常免疫" tabindex="-1">观察 4：真正稀缺的是&quot;攻击增益 / 魔法增益 / 破防 / 减伤 / 复活 / 全异常免疫&quot; <a class="header-anchor" href="#观察-4-真正稀缺的是-攻击增益-魔法增益-破防-减伤-复活-全异常免疫" aria-label="Permalink to &quot;观察 4：真正稀缺的是&quot;攻击增益 / 魔法增益 / 破防 / 减伤 / 复活 / 全异常免疫&quot;&quot;">​</a></h3><ul><li>攻击buff：<strong>仅 3 人</strong>（真夏のイーイー、魔女ミヤビ、黒門天・屍寺炎斎）。</li><li>魔法buff：<strong>仅 1 人</strong>（魔女ミヤビ，待核实幅度）。</li><li>贯通/破防：<strong>14 人</strong>。伤害减buff：<strong>5 人</strong>。异常解除：<strong>19 人</strong>。</li><li>复活：<strong>仅 1 人</strong>（超昂閃忍ナリカ）。全异常免疫：<strong>仅 1 人</strong>（体育祭のヤブルー）。</li><li><strong>推论</strong>：稀缺机制 = 高价值。这些才是&quot;贵&quot;的辅助/对策，应成为 S 级推荐的主体。</li></ul><h3 id="观察-5-异常免疫-领域光环-是免控位的性价比之王" tabindex="-1">观察 5：异常免疫&quot;领域光环&quot;是免控位的性价比之王 <a class="header-anchor" href="#观察-5-异常免疫-领域光环-是免控位的性价比之王" aria-label="Permalink to &quot;观察 5：异常免疫&quot;领域光环&quot;是免控位的性价比之王&quot;">​</a></h3><p>一类角色的固有效果是&quot;<strong>自身在场期间，全队免疫某类异常</strong>&quot;（被动、无消耗、不占出手）：</p><ul><li>制服ニャンコ / 閃忍ニャンコ / 魔女フタバ（R）：全队 毒·魅惑·束缚（+/眩晕）免疫。</li><li>神騎ハニーエル（R）：自身魔法免疫 + 全队 眩晕·束缚 免疫。</li><li><strong>推论</strong>：在魅惑/眩晕/束缚 重的 boss 战里，这种&quot;免控领域&quot;等于白送一个对策位，价值高于一次性解控。</li></ul><h3 id="观察-6-防御无视-贯通-独立乘区-对高防-boss-暴涨" tabindex="-1">观察 6：防御无视 / 贯通 = 独立乘区，对高防 boss 暴涨 <a class="header-anchor" href="#观察-6-防御无视-贯通-独立乘区-对高防-boss-暴涨" aria-label="Permalink to &quot;观察 6：防御无视 / 贯通 = 独立乘区，对高防 boss 暴涨&quot;">​</a></h3><p>伤害公式里防御按 <code>(1 - DEF/2000)</code> 衰减。无视防御是直接拿掉的独立乘区。</p><ul><li>閃忍マユリ（R）必杀 <strong>15× 无视防御</strong>（自爆式单体核弹）。</li><li>神騎ハニーエル（R）必杀 <strong>穿透蜂蜜魔免</strong>（针对魔免敌人）。</li><li><strong>推论</strong>：这类对&quot;高防/魔免&quot;的 raid boss 有非线性收益，应单列推荐。</li></ul><hr><h2 id="_3-第三步-我自己的评价框架-不依赖官方榜" tabindex="-1">3. 第三步：我自己的评价框架（不依赖官方榜） <a class="header-anchor" href="#_3-第三步-我自己的评价框架-不依赖官方榜" aria-label="Permalink to &quot;3. 第三步：我自己的评价框架（不依赖官方榜）&quot;">​</a></h2><p>我定下 4 条<strong>可验证</strong>的打分维度，按权重排序：</p><ol><li><strong>机制稀缺度 × 机制强度</strong>（最高权重） 拥有全游戏 ≤10 人的机制（不撤退 / 复活 / 全异常免疫 / 攻击增益 / 破防），且幅度经核验确实高。</li><li><strong>独立乘区叠加</strong>（公式推导） 伤害 = 攻击 × 连击 × (1−DEF/2000)/(1−MRES/2000) × (1+各增益%相加) × 必杀倍率。 增益是<strong>相加</strong>的，所以&quot;多一个不同类的增益来源&quot;比&quot;把单个增益堆更高&quot;更划算 → 稀有增益辅助价值被放大。</li><li><strong>站场能力</strong>（对抗核心失败条件） 不撤退 &gt; 异常免疫领域 &gt; 持续治疗/减伤。</li><li><strong>满突成本</strong>（养成铁律） 满突★5 的 R ≫ 零突★1 的 SSR。对新手，把稀缺机制落在 R/SR 上是最高性价比。</li></ol><p>注意：第 4 条只用于&quot;新手核心&quot;筛选；对&quot;通用 S 级&quot;我按机制强度排，不因稀有度扣分（SSR 满突后机制照样成立）。</p><hr><h2 id="_4-第四步-候选逐一核验-基于-details-txt-原文" tabindex="-1">4. 第四步：候选逐一核验（基于 _details.txt 原文） <a class="header-anchor" href="#_4-第四步-候选逐一核验-基于-details-txt-原文" aria-label="Permalink to &quot;4. 第四步：候选逐一核验（基于 _details.txt 原文）&quot;">​</a></h2><p>我对约 30 个候选打印了完整 必杀技+固有效果 文本，确认幅度/条件后才下结论。节选关键发现：</p><ul><li><strong>ビートソニック・アキレス(SSR)</strong>：不撤退 + 血量&lt;20% 回 25~50% 最大体力(1次)。攻击仅 475（非攻击上限），但&quot;不撤退&quot;本身已极稀有 → S 级站场。</li><li><strong>ブライドハルカ・リバース(SSR)</strong>：不撤退 + 攻击 521(上限) + 必杀 10% 即死（失败叠攻击上限 50%）+ &lt;10% 降仇恨。攻防一体强包。</li><li><strong>閃忍マユリ(R)</strong>：不撤退 + 必杀 <strong>15× 无视防御</strong>（自身承 100% 体力）。全游戏最暴力的单体自爆核弹，R 卡白送。</li><li><strong>超昂閃忍ナリカ(SSR)</strong>：自然体力消耗停在 25% + <strong>复活</strong>（火种）；双修 521/521/500。唯一复活位，泛用顶级。</li><li><strong>体育祭のヤブルー(SSR)</strong>：<strong>全异常免疫</strong>（全游戏独 1）+ 出战全队必杀+25% + 必杀全体 50%魅惑/75%束缚（巨型团队硬控）。唯一真·全免控核心。</li><li><strong>妹の1024(SSR)</strong>：普攻 80% 概率随机友军必杀+10%（自身同步）；必杀 场地速度+30% + 全队必杀+30%（叠 5 次）。最强充能核心之一。</li><li><strong>真夏のイーイー(SSR)</strong>：在场友军出战攻击+30%（盛夏+50/速度+25）；必杀横排 6×魔法 + 全队眩晕抵抗+50。攻击增益仅 3 人之一。</li><li><strong>黒門天・屍寺炎斎(SSR)</strong>：&lt;30%/65% 双节点 每秒 5% 回血 + 防御+100%；必杀 10×魔法（存活攻击+30% 上限 150%）。攻击增益仅 3 人之一。</li><li><strong>制服ニャンコ / 閃忍ニャンコ(SSR)</strong>：在场全队 毒·魅惑·束缚（+/眩晕）免疫 + 爆发治疗/攻防速增益。免控领域 + 治疗二合一。</li><li><strong>六の法杖セラフィール(SSR)</strong>：出战<strong>清除全队异常/减益</strong>（+回 15%）+ 场地 5%/s 回血。极稀有的&quot;被动解控&quot;治疗。</li><li><strong>鬼の斗羽大洋(SSR)</strong>：出战 敌方输出−25% / 我方+25%；必杀 <strong>全体攻防−60%</strong>（减益幅度罕见）。顶级破防减益。</li><li><strong>アイドルの奉輪こもり(SSR)</strong>：<strong>撤退时</strong>全队回 50% + 攻防+30%（死亡即全队大补）。独特的&quot;退场收益&quot;机制。</li><li><strong>神騎ハニーエル(R)</strong>：自身魔法免疫 + 全队 眩晕·束缚 免疫 + 必杀穿透蜂蜜魔免。R 卡里的魔免对策专精。</li><li><strong>エスカ・アメイズ(R)</strong>：必杀 全体 <strong>必中魅惑</strong>（魅惑免疫除外）——廉价的硬控对策。</li><li><strong>閃忍クサリ(R)</strong>：必杀 全体 <strong>强制眩晕</strong>（眩晕免疫除外）+ 束缚。廉价的硬控对策。</li><li><strong>閃忍サイカ(R)</strong>：出战 <strong>敌方时停 2.5~4 秒</strong>（全游戏独一份的&quot;开局冻结&quot;）+ 低速 3 人速度+25%（对闪忍彼岸花+300%）。机制独特。</li></ul><blockquote><p>另有大量 SSR 未逐一核验（共 259 个）。我的 S 级名单是&quot;<strong>经核验的突出样本</strong>&quot;，不是穷举；读者应按第 3 节的框架自行判断其余角色。</p></blockquote><hr><h2 id="_5-第五步-结论——v0-2-与-v0-1-的根本不同" tabindex="-1">5. 第五步：结论——v0.2 与 v0.1 的根本不同 <a class="header-anchor" href="#_5-第五步-结论——v0-2-与-v0-1-的根本不同" aria-label="Permalink to &quot;5. 第五步：结论——v0.2 与 v0.1 的根本不同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>v0.1（受官方榜影响）</th><th>v0.2（我的独立推理）</th></tr></thead><tbody><tr><td>推荐依据</td><td>&quot;官方榜最高评价 / 新手指南点名&quot;</td><td>机制稀缺度 + 公式乘区 + 满突成本</td></tr><tr><td>速度/充能辅助</td><td>当稀缺亮点</td><td>降权（126/105 人，通胀技能），只作新手补位</td></tr><tr><td>不撤退</td><td>仅作为附注</td><td>升为最高权重站场机制（仅 8 人）</td></tr><tr><td>攻击/魔法增益</td><td>未单列</td><td>单列 S 级（仅 3/1 人）</td></tr><tr><td>复活/全异常免疫</td><td>未单列</td><td>单列顶级（各仅 1 人）</td></tr><tr><td>新手核心</td><td>照搬官方点名卡</td><td>改为&quot;R/SR 中带稀缺机制的卡&quot;（FM77/闪忍真百合/神骑参宿四/神骑蜂蜜/闪忍彩香…）</td></tr></tbody></table><p>我不再声称&quot;官方说谁强&quot;。如果我的结论恰好与官方榜重合，那是因为<strong>强机制本来就稀缺、双方都看得到数据</strong>，而非我抄了榜单。</p><hr><h2 id="_6-第六步-不确定性与后续" tabindex="-1">6. 第六步：不确定性与后续 <a class="header-anchor" href="#_6-第六步-不确定性与后续" aria-label="Permalink to &quot;6. 第六步：不确定性与后续&quot;">​</a></h2><ul><li><strong>增益幅度全量对比</strong>：我只核验了约 30 个候选。&quot;攻击buff/速度buff 的具体数值&quot;仍缺全量数据，无法对所有 SSR 做精确排序。后续可扩展 <code>_detail.py</code> 抽取所有含&quot;攻撃力アップ/行動速度&quot;的原文并解析百分比，做数值排序。</li><li><strong>装备联动数值</strong>：&quot;超昂金&quot;按阵营人数加成的确切数值未量化，体系队收益只能定性。</li><li><strong>boss 实际数值</strong>：防御/魔抗/异常类型因 boss 而异，对策位选择需结合实际关卡数据，本推理只给&quot;机制可用性&quot;。</li><li><strong>budget/编成位限制</strong>：实际编队只有若干位，需在&quot;输出/辅助/治疗/对策&quot;间权衡，本日志给的是单卡价值，落地成队伍需另做组合优化。</li></ul><p>→ 这些留作 v0.3 的深化方向。</p><hr><h2 id="_7-v0-3-增补-副本-boss-×-配队推理-用户要求结合各种副本-boss-与-5人上场-分队伍" tabindex="-1">7. v0.3 增补：副本/BOSS × 配队推理（用户要求结合各种副本/BOSS 与&quot;5人上场+分队伍&quot;） <a class="header-anchor" href="#_7-v0-3-增补-副本-boss-×-配队推理-用户要求结合各种副本-boss-与-5人上场-分队伍" aria-label="Permalink to &quot;7. v0.3 增补：副本/BOSS × 配队推理（用户要求结合各种副本/BOSS 与&quot;5人上场+分队伍&quot;）&quot;">​</a></h2><h3 id="_7-1-我先纠正了自己对-分队伍-的理解" tabindex="-1">7.1 我先纠正了自己对&quot;分队伍&quot;的理解 <a class="header-anchor" href="#_7-1-我先纠正了自己对-分队伍-的理解" aria-label="Permalink to &quot;7.1 我先纠正了自己对&quot;分队伍&quot;的理解&quot;">​</a></h3><p>读 <code>raid.md</code> / <code>raid-formations.md</code>（<strong>系统事实页，非推荐榜</strong>）才明白：所谓&quot;上场5人、可分队伍&quot;在讨伐战里不是同场多队，而是<strong>接力轮换</strong>——体力每秒扣 2%（百分比，双防无效），单队 50 秒必退，所以高分打法是 <code>优先1(5)→优先2(15)→替补→星面50人</code> 多队接力。这直接推翻了 v0.2&quot;只列5人&quot;的呈现方式。</p><h3 id="_7-2-从-raid-机制推出的配队铁律-非官方推荐" tabindex="-1">7.2 从 raid 机制推出的配队铁律（非官方推荐） <a class="header-anchor" href="#_7-2-从-raid-机制推出的配队铁律-非官方推荐" aria-label="Permalink to &quot;7.2 从 raid 机制推出的配队铁律（非官方推荐）&quot;">​</a></h3><ul><li><strong>减伤率 debuff（降防）&gt;&gt; 攻击 buff</strong>：面对 75% 减伤 BOSS，降防带来的伤害提升是攻 buff 的 <strong>3 倍</strong>（60%减伤时1.5倍）。→ 这<strong>修正了 v0.2</strong>：我把&quot;攻击增益(3人)&quot;列 S 级，其实在 raid 里降防手（破防/贯通14人）更核心。</li><li><strong>单体 + 领域同名叠加</strong>：同类多角色同款只取最高（浪费），但单体型与领域型叠加 → 一单体一领域最优。</li><li><strong>必杀充能辅助 = 得分核心</strong>（FEVER 中必杀次数决定分）；<strong>默认带持续治疗</strong>；<strong>BREAK（确定点灯）比纯时停更值</strong>（破防=眩晕+1.5倍+重置攻击）。</li></ul><h3 id="_7-3-boss-参数-→-对策机制-→-角色匹配-独立推导" tabindex="-1">7.3 BOSS 参数 → 对策机制 → 角色匹配（独立推导） <a class="header-anchor" href="#_7-3-boss-参数-→-对策机制-→-角色匹配-独立推导" aria-label="Permalink to &quot;7.3 BOSS 参数 → 对策机制 → 角色匹配（独立推导）&quot;">​</a></h3><p>我把 7 个 BOSS 的参数（伤害量/减伤率/异常抗性/破防灯数/特殊机制）逐一对照，得出每BOSS必需对策，再从 v0.2 已核验角色里匹配：</p><ul><li>古纳冈：领域1%/s持续伤害 → <strong>持续治疗</strong>（制服ニャンコ/六の法杖セラフィール/魔女雫流）。</li><li>乌塔尔：小猫机制 → <strong>全体攻击/全体异常必杀</strong>清小猫（体育祭のヤブルー 全体魅惑+束缚 正好同时点灯）。</li><li>堕威大佛：高眩晕抗+破防灯仅3格 → <strong>确定点灯</strong>（エスカ・アメイズ R 必中魅惑、閃忍クサリ R 强制眩晕，无视抗性点灯）。</li><li>大往女：眩晕带束缚 → <strong>束缚免疫领域</strong>（制服ニャンコ/魔女フタバ R/神騎ハニーエル R）。</li><li>弗栗多：60%×4人极痛+双形态破盾+减速极高收益 → <strong>减速debuff + 降防100%破盾 + 体力停止居座</strong>（超昂奈理卡）。</li><li>黄金甜心：魔法减半 → 物理队优先或带&quot;咬甜心王子&quot;装备。</li><li>狂王：小狂王随从 → 全体必杀清随从。</li></ul><h3 id="_7-4-与-v0-2-的自洽验证" tabindex="-1">7.4 与 v0.2 的自洽验证 <a class="header-anchor" href="#_7-4-与-v0-2-的自洽验证" aria-label="Permalink to &quot;7.4 与 v0.2 的自洽验证&quot;">​</a></h3><p>v0.3 暴露 v0.2 两处需修正：① raid 里双防无效+百分比扣血，<strong>不撤退≠不扣血</strong>，真·适配 raid 居座的是&quot;体力停止衰减&quot;（超昂奈理卡），不撤退在高难主线才是神；② 降防 &gt; 攻buff。但 v0.2 的 R 卡 エスカ・アメイズ/閃忍クサリ 恰好命中&quot;确定点灯&quot;对策位——说明独立推理在堕威大佛/乌塔尔上自洽。</p><h3 id="_7-5-诚实留白" tabindex="-1">7.5 诚实留白 <a class="header-anchor" href="#_7-5-诚实留白" aria-label="Permalink to &quot;7.5 诚实留白&quot;">​</a></h3><p>弗栗多/乌塔尔专用&quot;减速角色&quot;&quot;全体异常清小猫&quot;持有者需查 <code>raid.md</code> 减速表与全体必杀清单全量核实；本版给机制方向+已核验示例，未穷举。详细团队方案见 <code>reco-team.md</code>。</p><hr><h3 id="_7-6-「降防收益-攻-buff-的-3-倍」严格证明-用户点名要求论证" tabindex="-1">7.6 「降防收益 = 攻 buff 的 3 倍」严格证明（用户点名要求论证） <a class="header-anchor" href="#_7-6-「降防收益-攻-buff-的-3-倍」严格证明-用户点名要求论证" aria-label="Permalink to &quot;7.6 「降防收益 = 攻 buff 的 3 倍」严格证明（用户点名要求论证）&quot;">​</a></h3><p><strong>结论先说</strong>：这不是我的发明，<code>raid.md</code>（系统事实页）原文就写了两条精确比例；且可从 <code>raid-buff-debuff.md</code> 的伤害公式严格推出。该&quot;3 倍&quot;指<strong>同百分比幅度下，降防带来的&quot;绝对伤害增量&quot;是攻 buff 的 3 倍</strong>（当 BOSS 减伤率 R=75% 时）。</p><h4 id="a-公式来源-raid-buff-debuff-md" tabindex="-1">(a) 公式来源（raid-buff-debuff.md） <a class="header-anchor" href="#a-公式来源-raid-buff-debuff-md" aria-label="Permalink to &quot;(a) 公式来源（raid-buff-debuff.md）&quot;">​</a></h4><p>副本最终伤害 = … × <strong>攻击力提升倍率</strong> × … × <strong>BOSS减伤率削减系数</strong> × … 且：<code>降低防御/降低闪避（敌方单体+领域合计上限50%）的总百分比，按比例削减副本BOSS的减伤率</code>。</p><h4 id="b-数学推导" tabindex="-1">(b) 数学推导 <a class="header-anchor" href="#b-数学推导" aria-label="Permalink to &quot;(b) 数学推导&quot;">​</a></h4><p>设 BOSS 减伤率 = R（如 0.75），基础裸伤（不含这两条）= <code>A·(1−R)</code>（A=基础攻击力×(其余乘区)）。</p><ul><li><strong>攻增益幅度 x</strong>（倍率 <code>1+x</code>）：伤害 = <code>A·(1+x)·(1−R)</code>，绝对增量 <code>Δ_atk = A·(1−R)·x</code>。</li><li><strong>降防幅度 x</strong>（把 R 按比例砍到 <code>R(1−x)</code>）：BOSS减伤率削减系数 = <code>1−R(1−x)</code>，伤害 = <code>A·(1−R+R·x)</code>，绝对增量 <code>Δ_def = A·R·x</code>。</li></ul><p>两者之比：<code>Δ_def / Δ_atk = (R·x) / ((1−R)·x) = R/(1−R)</code>。</p><ul><li>R=0.75 → 0.75/0.25 = <strong>3 倍</strong>。</li><li>R=0.60 → 0.60/0.40 = <strong>1.5 倍</strong>。</li></ul><h4 id="c-与-wiki-原文一一对应-raid-md-直接陈述" tabindex="-1">(c) 与 wiki 原文一一对应（raid.md 直接陈述） <a class="header-anchor" href="#c-与-wiki-原文一一对应-raid-md-直接陈述" aria-label="Permalink to &quot;(c) 与 wiki 原文一一对应（raid.md 直接陈述）&quot;">​</a></h4><ul><li>&quot;面对75%减伤BOSS，攻击增益效果与减伤降低收益比例 <strong>2.5:7.5</strong>；同等数值下，减伤降低带来的伤害提升是攻击增益效果的 <strong>3 倍</strong>。&quot; → 7.5/2.5=3 ✓</li><li>&quot;面对60%减伤BOSS，攻击增益效果与减伤降低收益比例 <strong>4:6</strong>；同等数值下，减伤降低带来的伤害提升是攻击增益效果的 <strong>1.5 倍</strong>。&quot; → 6/4=1.5 ✓</li><li>还说&quot;仅减轻率最低的古纳冈（50%），攻击buff与减轻率debuff的价值相等&quot; → R=0.5 时 R/(1−R)=1 ✓ 完全自洽。</li></ul><h4 id="d-关键前提与边界-避免误用" tabindex="-1">(d) 关键前提与边界（避免误用） <a class="header-anchor" href="#d-关键前提与边界-避免误用" aria-label="Permalink to &quot;(d) 关键前提与边界（避免误用）&quot;">​</a></h4><ol><li><strong>比较的是&quot;同百分比幅度&quot;</strong>：每 1% 降防的边际价值 = R/(1−R) × 每 1% 攻 buff。是&quot;单价&quot;比较，不是&quot;总收益&quot;比较。</li><li><strong>修正：50% 上限只针对&quot;降低闪避（回避buff）&quot;，正常降防无此上限</strong>。重读 <code>raid-buff-debuff.md</code> 明细表确认： <ul><li><code>降低防御</code> / <code>领域降低防御</code> 的数值列一路列到 <strong>100%</strong>，<strong>没有 50% 封顶</strong>（即&quot;正常降防buff 没限制&quot;）。</li><li><code>降低闪避</code> 那一行才标 <code>上限50%敌方单体</code>（领域侧另有标注）。</li><li>主句&quot;降低防御、领域降低防御、降低闪避（敌方单体+领域效果合计上限50%）&quot;的 50% 注，实际是挂在&quot;降低闪避&quot;上的，我先前把它误套到降低防御上。</li><li>含义：降低防御能堆得比 50% 更高（表见 60/75/80/100%），实战&quot;降防堆高 + 再叠攻 buff&quot;的空间比我之前写的更大；wiki 也说&quot;80%以上减轻率降低 + 攻击增益&quot;——这与&quot;降防无 50% 上限&quot;一致。攻 buff 仍靠单体+领域+永久相加叠高。</li></ul></li><li><strong>只适用于减伤率高的 BOSS</strong>：乌塔尔(65%)/弗栗多/黄金甜心(75%) 优势巨大；古纳冈(50%) 两者等价；普通主线/EX BOSS 减伤率低，攻 buff 相对更划算。</li><li>** raid 里双防无效、体力按百分比扣**——降防/攻 buff 都不影响生存，故纯比输出效率时此结论直接成立。</li></ol><blockquote><p>我 v0.3 在 reco-team.md / llm-recommend.md 里写的&quot;75%减伤BOSS时降防收益是攻buff的3倍（60%时1.5倍）&quot;即此结论，现已确认有公式+wiki 双重支撑，结论成立。</p></blockquote><h4 id="e-具体算例-a-1000-裸威力-攻-buff-与降防均取-50-幅度" tabindex="-1">(e) 具体算例（A=1000 裸威力，攻 buff 与降防均取 50% 幅度） <a class="header-anchor" href="#e-具体算例-a-1000-裸威力-攻-buff-与降防均取-50-幅度" aria-label="Permalink to &quot;(e) 具体算例（A=1000 裸威力，攻 buff 与降防均取 50% 幅度）&quot;">​</a></h4><p>D0 = 1000·(1−R)；攻buff50% = 1000·1.5·(1−R)；降防50% = 1000·(1 − R·0.5)。</p><table tabindex="0"><thead><tr><th>BOSS（R）</th><th>裸伤 D0</th><th>只上攻buff+50%</th><th>增量</th><th>只上降防50%</th><th>增量</th><th>倍数(降防/攻buff)</th></tr></thead><tbody><tr><td>低减伤 30%</td><td>700</td><td>1050</td><td>+350</td><td>850</td><td>+150</td><td>0.43×</td></tr><tr><td>古纳冈 50%</td><td>500</td><td>750</td><td>+250</td><td>750</td><td>+250</td><td><strong>1.0×（相等）</strong></td></tr><tr><td>堕威大佛/大往女/狂王 60%</td><td>400</td><td>600</td><td>+200</td><td>700</td><td>+300</td><td><strong>1.5×</strong></td></tr><tr><td>乌塔尔 65%</td><td>350</td><td>525</td><td>+175</td><td>675</td><td>+325</td><td>1.86×</td></tr><tr><td>弗栗多/黄金甜心 75%</td><td>250</td><td>375</td><td>+125</td><td>625</td><td>+375</td><td><strong>3.0×</strong></td></tr></tbody></table><p>读法：R=75% 时，攻buff 只多打 125 点（250→375），降防却多打 375 点（250→625），375/125=3 倍。R越低差距越小，到古纳冈(50%) 两者完全相等；低于 50% 降防反而更亏。 补充（修正上限误读后）：本表降防取 50% 仅是&quot;与攻buff同幅度&quot;的对照；而<strong>正常降低防御无 50% 上限</strong>，表列到 100%。若 R=75% 把降低防御堆到 100%，BOSS 减伤率→0，伤害=1000·(1−0)=1000（裸威力全吃）；即便只堆到 80%，伤害=1000·(1−0.75·0.2)=850。所以实战&quot;降低防御堆满 + 攻buff叠加&quot;远强于表里 50% 对照，结论只会更偏降防。降低闪避（回避buff）才是被 50% 上限约束的那个。 实战可叠加（攻buff+降防 = 1000·1.5·(1−R·(1−x_def))），R=75%、x_def=50% 时 = 937.5，逼近 1000 裸威力。</p><hr><h2 id="_8-v0-4-增补-如何从-370-角色里挑出-5-人-输出-生存-增益齐全-队-用户追问" tabindex="-1">8. v0.4 增补：如何从 370 角色里挑出 5 人&quot;输出+生存+增益齐全&quot;队（用户追问） <a class="header-anchor" href="#_8-v0-4-增补-如何从-370-角色里挑出-5-人-输出-生存-增益齐全-队-用户追问" aria-label="Permalink to &quot;8. v0.4 增补：如何从 370 角色里挑出 5 人&quot;输出+生存+增益齐全&quot;队（用户追问）&quot;">​</a></h2><h3 id="_8-1-用户的新约束" tabindex="-1">8.1 用户的新约束 <a class="header-anchor" href="#_8-1-用户的新约束" aria-label="Permalink to &quot;8.1 用户的新约束&quot;">​</a></h3><p>前几版我偏重&quot;输出 vs 降防&quot;的倍率比较，用户指出：还要考虑<strong>生存</strong>（治疗/减伤/免控）和<strong>增益</strong>（攻击速度、必杀充能——用户强调&quot;非常重要&quot;），但<strong>同场只上 5 人</strong>。问题变成：370 人里怎么调出一队职能齐全？这不能靠拍脑袋，要对全量数据做职能覆盖分析。</p><h3 id="_8-2-方法-不靠官方名单-对-char-data-json-打标签" tabindex="-1">8.2 方法（不靠官方名单，对 <code>char_data.json</code> 打标签） <a class="header-anchor" href="#_8-2-方法-不靠官方名单-对-char-data-json-打标签" aria-label="Permalink to &quot;8.2 方法（不靠官方名单，对 \`char_data.json\` 打标签）&quot;">​</a></h3><p>写 <code>_team_build.py</code>：给每个角色按&quot;队伍职能&quot;打标签（12 类：输出/降防/攻buff/增伤/速度/充能/治疗/减伤/免疫/解控/不撤退/复活/硬控），标签来自 必杀技+固有效果 的日中双文本正则匹配（修正了 v0.3 把&quot;防御20%ダウン/攻撃力50%アップ&quot;漏匹配的关键词 bug）。产物 <code>_team_build.txt</code>。</p><h3 id="_8-3-关键数据-实测稀缺度" tabindex="-1">8.3 关键数据（实测稀缺度） <a class="header-anchor" href="#_8-3-关键数据-实测稀缺度" aria-label="Permalink to &quot;8.3 关键数据（实测稀缺度）&quot;">​</a></h3><p>不撤退 <strong>8</strong> / 复活 <strong>1</strong>（全游戏唯一=超昂閃忍ナリカ）/ 降防 46 / 解控 19 / 增伤 54 / 减伤 60 / 免疫 62 / 治疗 99 / 充能 102 / 速度 126 / 攻buff 110 / 硬控 112 / 输出≈人人有。 <strong>最重要发现</strong>：用户强调的&quot;速度(126)/充能(102)&quot;其实<strong>持有量充足</strong>，并非瓶颈；真正卡脖子的是 <strong>不撤退(8)/复活(1)/降防(46)</strong>。所以&quot;速度/充能很重要&quot;≠&quot;难塞进队&quot;——它们人多，专挑&quot;顺带兼速度/充能&quot;的高密度卡即可，不必占独立槽。</p><h3 id="_8-4-5-框塞满的核心-职能密度" tabindex="-1">8.4 5 框塞满的核心 = 职能密度 <a class="header-anchor" href="#_8-4-5-框塞满的核心-职能密度" aria-label="Permalink to &quot;8.4 5 框塞满的核心 = 职能密度&quot;">​</a></h3><p>一个均衡队最少要覆盖 5 职能（输出+降防+速度+充能+治疗）。若每人单职，需 ≥6 槽 &gt; 5 人上限 → 不可能。解法：选&quot;一人兼多职&quot;的卡。 实测密度：<strong>≥3 职 46 人 / ≥4 职 37 人 / ≥5 职 10 人 / ≥6 职 7 人</strong>。例：<strong>小鬼の斗羽大洋</strong>（免疫+减伤+治疗+硬控+输出+降防，单卡顶 6 职）——一个槽同时解决 降防+治疗+免疫 三个刚需，是 5 框塞满的&quot;铰链&quot;。</p><h3 id="_8-5-贪心覆盖算法拼出的-4-套队-强制职能先补-余槽堆稀有权重" tabindex="-1">8.5 贪心覆盖算法拼出的 4 套队（强制职能先补，余槽堆稀有权重） <a class="header-anchor" href="#_8-5-贪心覆盖算法拼出的-4-套队-强制职能先补-余槽堆稀有权重" aria-label="Permalink to &quot;8.5 贪心覆盖算法拼出的 4 套队（强制职能先补，余槽堆稀有权重）&quot;">​</a></h3><ul><li><strong>A 顶配均衡队</strong>：エスカサファイア・ムーンライズ(输出+速度+增伤+减伤+解控+硬控) + 小鬼の斗羽大洋(降防+治疗+免疫) + ダンスクイーン・ピカ(充能+速度) + 超昂閃忍ナリカ(复活+免疫) + FM77(不撤退)。强制 5/5 覆盖、生存完整、总覆盖 13 职能。</li><li><strong>B 新手 R/SR 队</strong>：ビートノーブル・カノン(R) + 閃忍フクシュウチャン(SR) + ビートアミュレット・ノノノ(R) + FM77(R) + ビートアイドル・タマキ(R)。仅 R/SR 也 5/5 覆盖。</li><li><strong>C 居座队</strong>：A 骨架把 FM77 换成 ブライドハルカ・リバース(不撤退+自buff)。</li><li><strong>D 暴力输出队</strong>：A 骨架拉满输出权重。 （完整逐槽职能见 <code>reco-team.md</code> 2b 节）</li></ul><h3 id="_8-6-诚实留白-方法局限" tabindex="-1">8.6 诚实留白（方法局限） <a class="header-anchor" href="#_8-6-诚实留白-方法局限" aria-label="Permalink to &quot;8.6 诚实留白（方法局限）&quot;">​</a></h3><ul><li>关键词粗筛仍有误差：如&quot;攻防60%ダウン&quot;被同时计入 降防 与 减伤（敌攻下降=我方生存），属合理过宽；但&quot;防御.{0,6}アップ&quot;可能误捕非减伤文本，需二次核验。</li><li>&quot;输出&quot;代理用 <code>×倍率≥3 或 atk/mag≥450</code>，偏宽（≈人人有），故输出从不构成约束，真实约束是稀缺职——这反而正确反映了&quot;人人能打、难的是特殊机制&quot;。</li><li>速度/充能虽用户强调重要，但本分析只验证&quot;能否塞进 5 框&quot;（能），未量化&quot;具体加速/充能百分比&quot;对 FEVER 分数的边际收益（需查 <code>raid.md</code> 充能表）。</li><li>高密度卡多为节日/活动限定 SSR，新手 R/SR 队（B）已证明即便只 R/SR 也能凑齐 5 职能，但强度上限低。</li></ul><hr><h2 id="_9-v0-6-单角色固定强度量化模型-raid-专用-·-真实频率公式-·-通用可复用" tabindex="-1">9. v0.6 单角色固定强度量化模型（RAID 专用 · 真实频率公式 · 通用可复用） <a class="header-anchor" href="#_9-v0-6-单角色固定强度量化模型-raid-专用-·-真实频率公式-·-通用可复用" aria-label="Permalink to &quot;9. v0.6 单角色固定强度量化模型（RAID 专用 · 真实频率公式 · 通用可复用）&quot;">​</a></h2><h3 id="_9-1-用户意图澄清-场景固定" tabindex="-1">9.1 用户意图澄清 + 场景固定 <a class="header-anchor" href="#_9-1-用户意图澄清-场景固定" aria-label="Permalink to &quot;9.1 用户意图澄清 + 场景固定&quot;">​</a></h3><p>前文（v0.3/v0.4）偏&quot;队伍职能覆盖&quot;。用户指出：</p><ol><li><strong>这游戏强度模型不复杂</strong>——默认满星培养、培养压力小 → <strong>单个角色强度是固定值</strong>，可建数学模型。</li><li>推荐 5 人队时，要<strong>算出他们能打多少伤害、施加多少 buff/debuff</strong>（&quot;分数就是伤害，像考试一样&quot;）。</li><li>以后新增角色，只要<strong>读一遍角色详细信息</strong>套模型即出强度分，无需重训。</li></ol><p>进一步精炼（本版关键）：终局副本有 4 种（raid / B宇宙 / 广域战 / 全域战），<strong>只攻破 raid</strong>，其余三模式先占位。为建&quot;通用模型&quot;，用户要求把除「角色 kit + 真实战斗细节」外的一切<strong>全固定为常数</strong>：</p><ul><li><strong>BOSS 固定</strong>：机制常亮 · 固定伤害 · 体力固定消耗 -2%/s · 固定防御率 R（Step3 确认 = 0.50，古纳冈类）</li><li><strong>角色固定</strong>：满星100级 · 必杀/固有效果=觉醒+ · 觉醒强化固定到上限（速+3% / 充+15pt，Step3 确认）· 固定装备（3主+3副）</li><li><strong>真实战斗细节</strong>（extract_chars.py 抽 詳細ステータス）：行動速度(sec) / 必殺充填量(%) / 連撃率(%) → 强度 = 纯 kit + 真实战斗细节 函数；新增角色补进 <code>char_data.json</code> → 重跑 <code>_char_score.py</code> → 自动进 TOP40/分档/队伍打分。</li></ul><h3 id="_9-2-模型-机制事实-固定场景-真实频率-不参考任何官方榜" tabindex="-1">9.2 模型（机制事实 + 固定场景 + 真实频率，不参考任何官方榜） <a class="header-anchor" href="#_9-2-模型-机制事实-固定场景-真实频率-不参考任何官方榜" aria-label="Permalink to &quot;9.2 模型（机制事实 + 固定场景 + 真实频率，不参考任何官方榜）&quot;">​</a></h3><p><strong>特征解析</strong>（从 <code>char_data.json</code> 的 <code>stats_lv100</code>+必杀/固有效果日中文本正则提取 + <code>combat</code> 真实字段）： <code>base=max(攻撃力,魔法力)</code>@lv100；<code>ult_mult</code>=必杀倍率（只认 canon「敵?(単体|横列|全体)N倍」，觉醒+取最大）；<code>def_down/atk_buff/dmg_up/guard</code> %；真实 <code>行動速度(sec)/必殺充填量(%)/連撃率(%)</code>；<code>flag</code>: heal/immune/no_retreat/revive/hardcc/dec_cc/slow。</p><p><strong>固定场景常量（Step3 用户确认，均一行可改）</strong>：</p><ul><li>伤害公式乘数：FEVER=3 / CRIT=1.25 / BREAK=1.5</li><li>固定装备套：3主=装备提升値+300；3副=贴片B8(敌防御-30%)/B1(攻+30%)/B3(速+20%)</li><li>固定觉醒强化：攻速+3%(=+0.03, 行动间隔除法生效) / 充能+15pt(加法并入必杀充填量)</li><li>固定 BOSS：R_ref=0.50（古纳冈类）· 体力-2%/s · 机制常亮</li><li>連撃阈值=60%（基础连击率 0/50/70 三档跳变）</li></ul><p><strong>损伤频率模型（v0.6 核心，分数=秒伤）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>interval     = 行動速度(sec) / (1 + 副装速20% + 觉醒速3% + 自身速buff)   # 行动间隔(秒)</span></span>
<span class="line"><span>interval_ult= interval × (1 + 連撃率)         # 连击使行动计量条不前进→必杀/普攻节奏变慢（连击惩罚）</span></span>
<span class="line"><span>atks/s      = 1 / interval_ult</span></span>
<span class="line"><span>charge_eff  = min(100, 必殺充填量% + 觉醒充15pt)</span></span>
<span class="line"><span>必杀casts/s = (charge_eff/100) / interval_ult</span></span>
<span class="line"><span>combo_mult  = 1 + Σ 連撃率ⁿ×decay(n), decay=0.8/0.6/0.4/0.3(≥4击)   # 连击追加伤害(不暴击)</span></span>
<span class="line"><span>red_coeff   = 1 - R_ref*(1 - min(1, def_down + 副装降防30%))</span></span>
<span class="line"><span>crit      = 1.25  if (atk_buff&gt;0 or 副装攻30%) else 1.0</span></span>
<span class="line"><span>break_m   = 1.5   if hardcc else 1.0</span></span>
<span class="line"><span>base_hit  = (base+主装300) × (1+atk_buff+副装攻) × (1+dmg_up) × red_coeff</span></span>
<span class="line"><span>normal_DPS= (base_hit·crit + base_hit·(combo_mult-1)) × atks/s      # 基础击暴击，连击追加不暴击</span></span>
<span class="line"><span>ult_DPS   = base_hit × ult_mult × FEVER × break_m × 必杀casts/s</span></span>
<span class="line"><span>DPS_raw(c)= normal_DPS + ult_DPS</span></span></code></pre></div><p><strong>辅助/生存分</strong>（按机制稀缺度赋点，BOSS机制常亮→必须覆盖）：<code>UTIL = 100·复活 + 60·不撤退 + 40·免疫 + 35·奶 + 30·解控 + 25·硬控 + 30·guard</code>。 <strong>综合强度</strong>：<code>STRENGTH = 0.70·DPS_norm(0-100) + 0.30·UTIL_norm(0-100)</code>，分 <strong>T0(前10%)/T1(前30%)/T2(前60%)/T3(其余)</strong>。</p><h3 id="_9-3-验证-370-角色实跑-·-修复连击率单位-bug-artifact" tabindex="-1">9.3 验证（370 角色实跑 · 修复连击率单位 bug + artifact） <a class="header-anchor" href="#_9-3-验证-370-角色实跑-·-修复连击率单位-bug-artifact" aria-label="Permalink to &quot;9.3 验证（370 角色实跑 · 修复连击率单位 bug + artifact）&quot;">​</a></h3><ul><li>maxDPS=7,239；maxUTIL=140。</li><li><strong>修复连击率百分/小数单位 bug</strong>：combat 字段连击率以 %(如 30) 存储，公式原误当小数(1+30=31 倍减速)致连击角色 DPS 塌缩 1/30；现 kit_of 转小数(0.30)后排名自洽（修复前 閃忍アキラ DPS分仅 1.9，修复后 ~28，与降防100%×9 地位匹配）。</li><li><strong>必杀倍率 artifact 仍封死</strong>：只认「敵〇〇N倍」+ 严格兜底「必殺威力×N」，排除「人数×N%必杀威力アップ」团队缩放。</li><li><strong>TOP 与 §7.6 自洽</strong>：榜首被「降防 + 觉醒高倍率」统治——レジェンド・ハルカ(降防100%×9/攻50%/增50%/奶, 83.9)、幻忍コテツ(降防60%×9/攻30%/增50%/硬控, 74.3)、エスカ・オニキス(×9/攻150%/免疫/硬控, 70.3)、黒門天・屍寺炎斎(降防100%×10/攻30%/增50%, 63.4)。印证&quot;降防是伤害主杠杆 + 觉醒倍率=输出&quot;。</li><li><strong>連撃型验证（用户重点）</strong>：连击率≥60% 仅 3 人，必杀占比 78.6% / 52.1% / 20.6%。バビロニア・ニル(连击70%) 普攻DPS(2622) ≫ 必杀DPS(682)，确证「连击型必杀权重下降、普攻连击权重上升」。</li><li>模型内部一致性：D 暴力输出队 raw DPS(44,303) 远超 C 居座队(15,988) 属真实单位质量差（5 纯输出 vs 含生存），非 bug（详见 Part2）。</li></ul><h3 id="_9-4-part2-推荐-4-队-raid-伤害考试打分" tabindex="-1">9.4 Part2：推荐 4 队 raid 伤害考试打分 <a class="header-anchor" href="#_9-4-part2-推荐-4-队-raid-伤害考试打分" aria-label="Permalink to &quot;9.4 Part2：推荐 4 队 raid 伤害考试打分&quot;">​</a></h3><p>固定场景 + 7 BOSS 适配层（fit_mult：乌塔尔/狂王需全体、堕威大佛需硬控/全体、大往女需免疫/解控、古纳冈需治疗、弗栗多需减速/不撤退）。</p><ul><li>队伍聚合：各成员自身 interval/必杀充填量 → 求和 DPS；降防max(角色+副装30%) 攻buff× 增伤× 暴击× 击破。</li><li>综合平均得分：<strong>D 暴力输出队 39,872 &gt; C 居座队 16,154 &gt; A 顶配均衡 12,730 &gt; B 新手 7,757</strong>。</li><li>D 在乌塔尔/狂王(缺全体) fit 0.60/0.70 扣分，单 BOSS 可能不敌 C；C 全 BOSS 最稳。</li></ul><h3 id="_9-5-诚实留白" tabindex="-1">9.5 诚实留白 <a class="header-anchor" href="#_9-5-诚实留白" aria-label="Permalink to &quot;9.5 诚实留白&quot;">​</a></h3><ul><li><strong>觉醒强化单位（Step3 确认）</strong>：+3攻速/+15充能 按&quot;速+0.03(间隔除法) / 充+15pt(加法)&quot;。若游戏内单位是别的标度，改 <code>_char_score.py</code> 顶部 AWK_SPEED/AWK_CHARGE 两行即可（所有角色相同，仅线性平移，不影响相对排名）。</li><li>R_ref=0.50（Step3 确认，古纳冈类）；若以最难 75% 为基准，改一行即可（降防权重随 §7.6 R/(1-R) 升至 3 倍，排名微调）。</li><li>連撃阈值 60%（Step3 确认），基础连击率 0/50/70 三档；模型对连击用连续惩罚因子(interval×(1+連撃率))，不是硬二分类。</li><li>真实战斗细节来自 <code>char_data.json.combat</code>（extract_chars.py 抽 詳細ステータス），若源站数值更新重跑 extract 即可。</li><li>固定装备套数值（主装+300/副装三件套）据 equipment.md 合理设定；若实战标准配装不同，改常量块即可。</li><li>UTIL 点权与 DPS 0.70/UTIL 0.30 为文档化折中；fit_mult 为 BOSS 对策经验系数（非严格推导）。</li><li>团队缩放 buff（如&quot;人数×50%必杀威力&quot;）未计入单角色分（需特定队伍组合才触发），属保守处理。</li></ul><h3 id="_9-6-四模式占位" tabindex="-1">9.6 四模式占位 <a class="header-anchor" href="#_9-6-四模式占位" aria-label="Permalink to &quot;9.6 四模式占位&quot;">​</a></h3><p>raid 已攻破；<strong>B宇宙 / 广域战 / 全域战</strong> 仅占位——同框架接入只需替换&quot;场景常量块 + 适配层&quot;，无需重写模型。</p><hr><h2 id="_10-v0-7-修正-真实觉醒属性强化表-2026-07-30-用户提供" tabindex="-1">10. v0.7 修正：真实觉醒属性强化表（2026-07-30 用户提供） <a class="header-anchor" href="#_10-v0-7-修正-真实觉醒属性强化表-2026-07-30-用户提供" aria-label="Permalink to &quot;10. v0.7 修正：真实觉醒属性强化表（2026-07-30 用户提供）&quot;">​</a></h2><h3 id="_10-1-用户纠错" tabindex="-1">10.1 用户纠错 <a class="header-anchor" href="#_10-1-用户纠错" aria-label="Permalink to &quot;10.1 用户纠错&quot;">​</a></h3><p>用户给出游戏内真实「属性强化（觉醒）」表，推翻 v0.6 两个 Step3 常数：</p><ul><li><s>速+3%（间隔除法）</s> → <strong>行动速度 -0.1×20次 = 最多 -2 秒（扁平秒数），强化下限 3 sec</strong>。已 ≤3s 的角色零收益。</li><li><s>充+15pt</s> → <strong>必杀充能 +0.3×20次 = 最多 +6pt，强化上限 15%</strong>。基础 ≥15 的角色零收益（但保留原值，如 20% 不削）。</li><li>用户强调：<strong>上限 3s/15% 是对的，但不是人人可达——强化次数有限</strong>（速最高只 -2，充最高只 +6）。</li><li>另采纳表内 攻/魔 +1%×20=+20%（全员同幅，进 base_hit，抬绝对 DPS 不改排名）。</li><li><strong>连击率 +1×20=+20(上限50%) 不采纳</strong>：基础连击 0/50/70 三档，50/70 已达/超上限无收益；0 档必杀型点满后 interval_ult×1.2 反拖慢必杀节奏（连击使行动条不前进），理性玩家不点。</li></ul><h3 id="_10-2-公式改动-char-score-py-v0-7" tabindex="-1">10.2 公式改动（<code>_char_score.py</code> v0.7） <a class="header-anchor" href="#_10-2-公式改动-char-score-py-v0-7" aria-label="Permalink to &quot;10.2 公式改动（\`_char_score.py\` v0.7）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eff_speed  = max(行動速度 - 2.0, 3.0)                    # 觉醒扁平减秒（替换旧除法+3%）</span></span>
<span class="line"><span>interval   = eff_speed / (1 + 副装速20% + 自身速buff)</span></span>
<span class="line"><span>charge_eff = 充≥15 ? 原值 : min(充+6, 15)                # 替换旧 min(100, 充+15)</span></span>
<span class="line"><span>base_hit   = (base×1.20 + 主装300) × ...                 # 新增觉醒攻魔+20%</span></span></code></pre></div><h3 id="_10-3-结果变化-370-实跑" tabindex="-1">10.3 结果变化（370 实跑） <a class="header-anchor" href="#_10-3-结果变化-370-实跑" aria-label="Permalink to &quot;10.3 结果变化（370 实跑）&quot;">​</a></h3><ul><li>maxDPS 7,239→<strong>6,181</strong>（充能砍半→必杀频率全员下降）。</li><li><strong>排名洗牌，コテツ 登顶</strong>：幻忍コテツ 75.4 &gt; レジェンド・ハルカ 69.3 &gt; 黒門天 63.7 &gt; ブライド・スバル 58.6 &gt; エスカ・オニキス 57.5。 <ul><li>机制解释：ハルカ 基础 3.0s 已在强化下限，觉醒速<strong>零收益</strong>；コテツ 4.0s→3.0s 完全追平，且连击 0%（ハルカ 10% 有节奏惩罚）。<strong>觉醒下限 3s 把基础 3~5s 全拉平 →&quot;基础速度快&quot;不再是护城河，连击 0% 成隐性优势。</strong></li></ul></li><li>連撃型必杀占比进一步下降（充+6 后）：切裂余命 68.8% / キリエル 39.5% / バビロニア・ニル 13.1%（普攻 2,897 ≫ 必杀 438）。</li><li>四队结论不变，数值更新：D 33,897(raw 37,664) &gt; C 16,625 &gt; A 12,750 &gt; B 8,014。</li></ul><h3 id="_10-4-装备项待办-上一轮遗留" tabindex="-1">10.4 装备项待办（上一轮遗留） <a class="header-anchor" href="#_10-4-装备项待办-上一轮遗留" aria-label="Permalink to &quot;10.4 装备项待办（上一轮遗留）&quot;">​</a></h3><p>用户默认输出位配装 = 满级 火箭引擎+冲击腰带+仁王纳豆（主装三件套），当前模型仍是占位（主装+300 / 副装贴片 B8·B1·B3）。等用户给三件满级数值 + 拍板贴片去留（A 保留 / B 只算三件）后替换常量块。 → <strong>已于 §11 (v0.8) 解决。</strong></p><hr><h2 id="_11-v0-8-修正-真实两件配装-2026-07-30-用户拍板" tabindex="-1">11. v0.8 修正：真实两件配装（2026-07-30 用户拍板） <a class="header-anchor" href="#_11-v0-8-修正-真实两件配装-2026-07-30-用户拍板" aria-label="Permalink to &quot;11. v0.8 修正：真实两件配装（2026-07-30 用户拍板）&quot;">​</a></h2><h3 id="_11-1-用户决策" tabindex="-1">11.1 用户决策 <a class="header-anchor" href="#_11-1-用户决策" aria-label="Permalink to &quot;11.1 用户决策&quot;">​</a></h3><ul><li><strong>副装贴片全删</strong>（B8降防30%/B1攻30%/B3速20%）：多变量。</li><li><strong>仁王纳豆也删</strong>：有的角色技能效果与纳豆冲突（如体力停衰/居座类），会增加变量。</li><li>默认<strong>仅两件主装</strong>（满级）： <ul><li>火箭引擎/咆哮猛虎：<strong>行动速度 -50%</strong>（百分比缩短）</li><li>冲击腰带：<strong>攻击力&amp;魔法力 +50%</strong></li></ul></li><li>旧占位（主装+300 扁平）一并作废。</li></ul><h3 id="_11-2-公式改动-char-score-py-v0-8" tabindex="-1">11.2 公式改动（<code>_char_score.py</code> v0.8） <a class="header-anchor" href="#_11-2-公式改动-char-score-py-v0-8" aria-label="Permalink to &quot;11.2 公式改动（\`_char_score.py\` v0.8）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>interval  = max(行動速度-2, 3) × (1 - 0.50) / (1 + 自身速buff)   # 火箭乘法，作用于觉醒后</span></span>
<span class="line"><span>red_coeff = 1 - R×(1 - min(1, 降防))        # 降防只剩角色 kit 自带（无 30% 打底）</span></span>
<span class="line"><span>base_hit  = base×1.20 × (1 + 攻buff + 0.50) × (1+增伤) × red_coeff   # 腰带+50% 加算</span></span>
<span class="line"><span>crit      = 1.25 常驻（腰带全员带 → 全员一致，不影响相对排名）</span></span></code></pre></div><p>常数：<code>EQ_ROCKET_SPEED=0.50 / EQ_BELT_ATK=0.50</code>（删 <code>MAIN_EQ_ATK/SUB_DEF_DOWN/SUB_ATK_BUFF/SUB_SPEED</code>）。 模型假设：火箭作用顺序 = 先觉醒扁平减秒（下限3s）再装备乘法 ×0.5；若实际相反，3s 下限角色数值微变、排名几乎不动。</p><h3 id="_11-3-结果变化-370-实跑-输出-score-v08-out-txt" tabindex="-1">11.3 结果变化（370 实跑，输出 <code>_score_v08_out.txt</code>） <a class="header-anchor" href="#_11-3-结果变化-370-实跑-输出-score-v08-out-txt" aria-label="Permalink to &quot;11.3 结果变化（370 实跑，输出 \`_score_v08_out.txt\`）&quot;">​</a></h3><ul><li>maxDPS 6,181→<strong>6,595</strong>（火箭-50% 提频 &gt; 腰带替换损失）。</li><li><strong>排名再洗牌，ハルカ 重回 TOP1</strong>：レジェンド・ハルカ 78.9(降防100%) &gt; 幻忍コテツ 75.4(降防60%，DPS分100 仍 maxDPS) &gt; 黒門天 73.0(降防100%×10) &gt; ブライド・スバル 61.3 &gt; 真夏のハルカ 55.3 &gt; 閃忍アキラ 53.4。</li><li><strong>核心洞察：删掉副装 30% 降防打底后，kit 自带降防价值暴涨</strong>——v0.7 人人白嫖 30% 打底稀释了 kit 降防；v0.8 「降防100% vs 60%」= red_coeff 1.00 vs 0.80 = 25% 伤害差，直接改写头名。降防重新成为最强单体杠杆（与 §7.6 一致）。</li><li>火箭 -50% 是全员等比乘法 → 不改相对排名；觉醒 3s 下限拉平速度的洞察（§10.3）仍成立。</li><li>四队：D 42,281(raw 46,979，降防100% 独享 red_coeff=1.00 完全免削减) &gt; C 16,529 &gt; A 12,541 &gt; B 7,344。D 的优势较 v0.7 进一步扩大（C/A/B 失去 30% 降防打底更痛）。</li></ul>`,137)])])}const q=o(n,[["render",l]]);export{h as __pageData,q as default};
